const b = $input.first().json.body || {};
    const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
    const mail = /^[^@\s]+@[^@\s]+\.[^@\s]+$/;
    const pid = uuid.test(b.project_id || '') ? b.project_id : null;
    const filter = pid ? "AND project_id = '" + pid + "'::uuid " : '';
    const sql_tasks = 'SELECT id,title,required_skills,project_id FROM tasks WHERE assignee_id IS NULL ' + filter +
      "AND status <> 'DONE' AND array_length(required_skills,1) > 0 ORDER BY created_at";
    const min = Number(b.min_score);
    return [{ json: {
      sql_tasks,
      min_score: isFinite(min) && min >= 0 && min <= 100 ? min : 40,
      notify_email: mail.test(b.notify_email || '') ? b.notify_email : 'htchannelas@gmail.com',
    } }];

const tasks = $('Collect Tasks').first().json.tasks;
    const min = $('Prepare Input').first().json.min_score;
    const members = $input.all().map((i) => i.json).filter((m) => m.id)
      .map((m) => Object.assign({}, m, { load: Number(m.current_load), max: Number(m.max_workload) }));
    const norm = (s) => String(s).toLowerCase().trim();
    const r1 = (x) => Math.round(x * 10) / 10;
    const out = [];
    for (const t of tasks) {
      const req = (t.required_skills || []).map(norm);
      const ranking = members.map((m) => {
        const ms = (m.skills || []).map(norm);
        const matched = req.filter((r) => ms.some((s) => s === r || s.includes(r) || r.includes(s)));
        const skill = req.length ? (matched.length / req.length) * 100 : 0;
        const loadScore = m.max > 0 ? Math.max(0, 1 - m.load / m.max) * 100 : 0;
        const prod = Math.min(100, Number(m.productivity_score) || 0);
        return {
          member_id: m.id, member_name: m.full_name, matched,
          skill: r1(skill), load_score: r1(loadScore), productivity: r1(prod),
          total: r1(skill * 0.6 + loadScore * 0.25 + prod * 0.15),
          has_capacity: m.load < m.max,
        };
      }).filter((r) => r.has_capacity).sort((a, b) => b.total - a.total);
      const best = ranking[0] || null;
      const qualified = !!best && best.skill > 0 && best.total >= min;
      if (qualified) members.find((m) => m.id === best.member_id).load++;
      out.push({ json: {
        task_id: t.id, title: t.title, project_id: t.project_id, required_skills: t.required_skills,
        qualified, best, top3: ranking.slice(0, 3),
        sql: qualified
          ? "UPDATE tasks SET assignee_id = '" + best.member_id + "'::uuid, updated_at = CURRENT_TIMESTAMP WHERE id = '" + t.id + "'::uuid RETURNING id, title, assignee_id"
          : 'SELECT 1 AS skipped',
      } });
    }
    return out;

const rs = $('Score Matching').all().map((i) => i.json);
    const lines = rs.map((r) => '- ' + r.title + ' | yêu cầu: ' + (r.required_skills || []).join(', ') + ' | ' +
      (r.qualified
        ? 'GÁN CHO ' + r.best.member_name + ' (skill ' + r.best.skill + '%, tải ' + r.best.load_score + ', năng suất ' + r.best.productivity + ', tổng ' + r.best.total + ')'
        : 'CHƯA GÁN (cần review)')).join('\n');
    const prompt = 'Bạn là PM. Dưới đây là kết quả tự động khớp kỹ năng cho các task:\n' + lines +
      '\n\nViết nhận xét ngắn gọn bằng tiếng Việt (tối đa 120 từ) giải thích vì sao các task được gán như vậy và nêu rủi ro nếu có. Không dùng markdown.';
    return [{ json: { prompt } }];

const rs = $('Score Matching').all().map((i) => i.json);
    const email = $('Prepare Input').first().json.notify_email;
    let explain;
    try { explain = $input.first().json.content.parts[0].text; } catch (e) { explain = '(AI không trả về giải thích)'; }
    const q = (s) => "'" + String(s ?? '').replace(/'/g, "''") + "'";
    const esc = (s) => String(s).replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c]));
    const assigned = rs.filter((r) => r.qualified).length;
    const review = rs.length - assigned;
    const metrics = { total: rs.length, assigned, needs_review: review };
    const sql = 'INSERT INTO reports (project_id, report_type, risk_score, ai_summary, metrics) VALUES (' +
      q(rs[0].project_id) + "::uuid, 'SKILL_MATCHING', " + (rs.length ? (review / rs.length * 100).toFixed(2) : 0) + ', ' +
      q(explain) + ', ' + q(JSON.stringify(metrics)) + '::jsonb) RETURNING id';
    const rows = rs.map((r) => '<tr><td>' + esc(r.title) + '</td><td>' + (r.qualified ? esc(r.best.member_name) + ' (' + r.best.total + ')' : '⚠️ cần review') + '</td></tr>').join('');
    const html = '<h2>🎯 Skill Matrix Matching</h2><p>Gán: <b>' + assigned + '</b> | Cần review: <b>' + review + '</b></p>' +
      '<table border="1" cellpadding="6" style="border-collapse:collapse"><tr><th>Task</th><th>Kết quả</th></tr>' + rows + '</table>' +
      '<h3>Nhận xét AI</h3><p>' + esc(explain) + '</p>';
    return [{ json: {
      sql, notify_email: email,
      subject: '🎯 [Luồng 3] Khớp kỹ năng: ' + assigned + ' gán, ' + review + ' cần review',
      html,
      response: { success: true, ...metrics, ai_summary: explain,
        results: rs.map((r) => ({ task: r.title, qualified: r.qualified, assignee: r.best ? r.best.member_name : null, score: r.best ? r.best.total : null })) },
    } }];
